#include "listener.hpp"

// Value parameters retain the upstream callback and coroutine ownership contract.
// NOLINTNEXTLINE(performance-unnecessary-value-param)
listener::listener(webcpp::asio::io_context& ioc, tcp::endpoint endpoint,
                   boost::shared_ptr<shared_state> const& state)
    : ioc_(ioc), acceptor_(ioc), state_(state) {
    beast::error_code ec;

    // Open the acceptor
    // The ec output and the returned reference carry the same operation status.
    // NOLINTNEXTLINE(bugprone-unused-return-value)
    static_cast<void>(acceptor_.open(endpoint.protocol(), ec));
    if (ec) {
        fail(ec, "open");
        return;
    }

    // Allow address reuse
    // The ec output and the returned reference carry the same operation status.
    // NOLINTNEXTLINE(bugprone-unused-return-value)
    static_cast<void>(acceptor_.set_option(net::socket_base::reuse_address(true), ec));
    if (ec) {
        fail(ec, "set_option");
        return;
    }

    // Bind to the server address
    // The ec output and the returned reference carry the same operation status.
    // NOLINTNEXTLINE(bugprone-unused-return-value)
    static_cast<void>(acceptor_.bind(endpoint, ec));
    if (ec) {
        fail(ec, "bind");
        return;
    }

    // Start listening for connections
    // The ec output and the returned reference carry the same operation status.
    // NOLINTNEXTLINE(bugprone-unused-return-value)
    static_cast<void>(acceptor_.listen(net::socket_base::max_listen_connections, ec));
    if (ec) {
        fail(ec, "listen");
        return;
    }
}

void listener::run() {
    // The new connection gets its own strand
    acceptor_.async_accept(net::make_strand(ioc_),
                           beast::bind_front_handler(&listener::on_accept, shared_from_this()));
}

// Report a failure
// Member shape is part of the upstream Body or bound-callback interface.
// NOLINTNEXTLINE(readability-convert-member-functions-to-static)
void listener::fail(beast::error_code ec, char const* what) {
    // Don't report on canceled operations
    if (ec == net::error::operation_aborted) {
        return;
    }
    std::cerr << what << ": " << ec.message() << "\n";
}

// Handle a connection
void listener::on_accept(beast::error_code ec, tcp::socket socket) {
    if (ec) {
        {
            fail(ec, "accept");
            return;
        }
    }
    {
        // Launch a new session for this connection
        boost::make_shared<http_session>(std::move(socket), state_)->run();
    }

    // The new connection gets its own strand
    acceptor_.async_accept(net::make_strand(ioc_),
                           beast::bind_front_handler(&listener::on_accept, shared_from_this()));
}
